// AuthServiceHandler is an implementation of the brigade.v1.AuthService service.
type AuthServiceHandler interface {
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	Refresh(context.Context, *connect.Request[v1.RefreshRequest]) (*connect.Response[v1.RefreshResponse], error)
	// Me возвращает текущего пользователя по access-токену (из cookie или Bearer).
	Me(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.User], error)
	// GetServerInfo сообщает клиенту режим работы сервера (см. ServerInfo).
	GetServerInfo(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.ServerInfo], error)
	Logout(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.Empty], error)
	// GetClaudeSettings возвращает состояние Claude-настроек пользователя (только флаг
	// token_set — значение токена не раскрывается).
	GetClaudeSettings(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.ClaudeSettings], error)
	// SetClaudeToken задаёт (или очищает пустым значением) подписочный токен Claude
	// пользователя. Возвращает обновлённое состояние (token_set).
	SetClaudeToken(context.Context, *connect.Request[v1.SetClaudeTokenRequest]) (*connect.Response[v1.ClaudeSettings], error)
	GetCodexSettings(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.CodexSettings], error)
	SetCodexApiKey(context.Context, *connect.Request[v1.SetCodexApiKeyRequest]) (*connect.Response[v1.CodexSettings], error)
	SetCodexChatGPTAuth(context.Context, *connect.Request[v1.SetCodexChatGPTAuthRequest]) (*connect.Response[v1.CodexSettings], error)
	StartCodexLogin(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.CodexLogin], error)
	GetCodexLogin(context.Context, *connect.Request[v1.GetCodexLoginRequest]) (*connect.Response[v1.CodexLogin], error)
	CancelCodexLogin(context.Context, *connect.Request[v1.CancelCodexLoginRequest]) (*connect.Response[v1.Empty], error)
	DisconnectCodexChatGPT(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.CodexSettings], error)
	SetCodexDefaultProfile(context.Context, *connect.Request[v1.SetCodexDefaultProfileRequest]) (*connect.Response[v1.CodexSettings], error)
	// GetMemorySettings возвращает настройки личной памяти пользователя (git-remote).
	GetMemorySettings(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.MemorySettings], error)
	// SetMemorySettings задаёт git-remote личной памяти. Возвращает обновлённое состояние.
	SetMemorySettings(context.Context, *connect.Request[v1.SetMemorySettingsRequest]) (*connect.Response[v1.MemorySettings], error)
	// GetNtfySettings возвращает настройки push-уведомлений пользователя (server/topic/events
	// + флаг token_set; значение токена не раскрывается).
	GetNtfySettings(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.NtfySettings], error)
	// SetNtfySettings задаёт server/topic/token/events персональных ntfy-уведомлений.
	// Возвращает обновлённое состояние.
	SetNtfySettings(context.Context, *connect.Request[v1.SetNtfySettingsRequest]) (*connect.Response[v1.NtfySettings], error)
	// GetAgentRuntime возвращает режим исполнения сессий (local|docker), доступные
	// docker-контексты и признак «нужен перезапуск».
	GetAgentRuntime(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.AgentRuntimeSettings], error)
	// SetAgentRuntime задаёт режим и docker-контекст (только десктопная инсталляция).
	SetAgentRuntime(context.Context, *connect.Request[v1.SetAgentRuntimeRequest]) (*connect.Response[v1.AgentRuntimeSettings], error)
	// GetAgentImages возвращает образы контейнеров агента пользователя, базовый образ и
	// состояние квоты.
	GetAgentImages(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.AgentImagesSettings], error)
	// SetAgentImages перезаписывает список образов пользователя. Образ, который не удалось
	// подтянуть, не пригоден для сессий или не влезает в квоту, отклоняет весь запрос.
	SetAgentImages(context.Context, *connect.Request[v1.SetAgentImagesRequest]) (*connect.Response[v1.AgentImagesSettings], error)
	// TestNtfy шлёт пробное уведомление по СОХРАНЁННЫМ настройкам пользователя: проверка
	// топика/сервера/токена из UI. Ошибка доставки возвращается вызывающему — иначе
	// неверные настройки обнаруживались бы только по молчанию в реальной сессии.
	TestNtfy(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.Empty], error)
	// GetSSHSettings возвращает публичный SSH-ключ агента пользователя, генерируя пару при
	// первом обращении (приватный ключ наружу не отдаётся).
	GetSSHSettings(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.SSHSettings], error)
	// RegenerateSSHKey перевыпускает пару SSH-ключей агента (старый публичный ключ в GitHub
	// после этого недействителен). Возвращает новый публичный ключ.
	RegenerateSSHKey(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.SSHSettings], error)
}

